// CAN-FD's largest payload, aliased from the public limits header so a bound
// change at that surface reaches this one.
constexpr std::size_t max_can_fd_payload_bytes =
    static_cast<std::size_t>(aletheia::max_frame_byte_count);

// The (value, extended-flag) pair every FFI signature takes for a CAN id.
struct WireCanId {
    std::uint32_t value;
    std::uint8_t extended;
};

using HsInitFn = void (*)(int*, char***);
using AletheiaInitFn = void* (*)();
using AletheiaProcessFn = char* (*)(void*, const char*);
using AletheiaSendFrameFn = char* (*)(void*, std::uint64_t, std::uint32_t, std::uint8_t,
                                      std::uint8_t, const std::uint8_t*, std::uint8_t, std::uint8_t,
                                      std::uint8_t, std::uint8_t, std::uint8_t);
using AletheiaFreeStrFn = void (*)(char*);
using AletheiaCloseFn = void (*)(void*);

// CAN error/remote event endpoints.
using AletheiaSendErrorFn = char* (*)(void*, std::uint64_t);
using AletheiaSendRemoteFn = char* (*)(void*, std::uint64_t, std::uint32_t, std::uint8_t);

// Binary FFI endpoints (no JSON input serialization).
using AletheiaNoArgFn = char* (*)(void*);
using AletheiaExtractFn = char* (*)(void*, std::uint32_t, std::uint8_t, std::uint8_t,
                                    const std::uint8_t*, std::uint8_t);

// Binary output endpoints (return status code, write bytes to caller buffer).
using AletheiaBuildFrameBinFn = std::int8_t (*)(void*, std::uint32_t, std::uint8_t, std::uint8_t,
                                                std::uint32_t, const std::uint32_t*,
                                                const std::int64_t*, const std::int64_t*,
                                                std::uint8_t*, char**);
using AletheiaUpdateFrameBinFn = std::int8_t (*)(void*, std::uint32_t, std::uint8_t, std::uint8_t,
                                                 const std::uint8_t*, std::uint8_t, std::uint32_t,
                                                 const std::uint32_t*, const std::int64_t*,
                                                 const std::int64_t*, std::uint8_t*, char**);
using AletheiaExtractBinFn = std::int8_t (*)(void*, std::uint32_t, std::uint8_t, std::uint8_t,
                                             const std::uint8_t*, std::uint8_t, std::uint8_t**,
                                             std::uint32_t*, char**);
using AletheiaFreeBufFn = void (*)(std::uint8_t*);
} // namespace

// ---------------------------------------------------------------------------
// Byte ↔ uint8_t pointer aliasing at the FFI boundary.
//
// The C++ surface holds payloads as std::span<const std::byte> / std::vector<
// std::byte>, while the Haskell FFI signatures expect const std::uint8_t* and
// std::uint8_t*. The reinterpret_cast here is well-defined: [basic.types]
// guarantees std::byte is layout-compatible with unsigned char, and std::
// uint8_t is unsigned char on every platform we target (Clang 22 on Linux
// x86_64/ARM64). The NOLINTs below are centralised so the FFI call
// sites stay free of noise; every byte-cast flows through these three fns.
static auto as_u8(const std::byte* p) -> const std::uint8_t* {
    // NOLINTNEXTLINE(cppcoreguidelines-pro-type-reinterpret-cast)
    return reinterpret_cast<const std::uint8_t*>(p);
}

static auto as_u8(std::byte* p) -> std::uint8_t* {
    // NOLINTNEXTLINE(cppcoreguidelines-pro-type-reinterpret-cast)
    return reinterpret_cast<std::uint8_t*>(p);
}

static auto as_byte(const std::uint8_t* p) -> const std::byte* {
    // NOLINTNEXTLINE(cppcoreguidelines-pro-type-reinterpret-cast)
    return reinterpret_cast<const std::byte*>(p);
}

static auto wire_can_id(const CanId& id) -> WireCanId {
    return {.value = can_id_value(id),
            .extended = static_cast<std::uint8_t>(can_id_is_extended(id) ? 1 : 0)};
}

// CAN-FD's largest payload is 64 bytes; tighten the FFI bound so a malformed
// caller cannot smuggle a 65 to 255 byte payload into the Haskell core before
// it does its own length check.
static auto payload_bound_error(std::span<const std::byte> data) -> std::optional<AletheiaError> {
    if (data.size() <= max_can_fd_payload_bytes)
        return std::nullopt;
    return AletheiaError{ErrorKind::Validation, "data length exceeds " +
                                                    std::to_string(max_can_fd_payload_bytes) +
                                                    " bytes (CAN-FD max)"};
}

namespace {

// Backend wrapping libaletheia-ffi.so via dlopen.  Lifecycle invariant:
// the GHC RTS is process-global, so the destructor must NOT call
// `hs_exit()` (the RTS does not support reinitialisation) and must NOT
// `dlclose()` the library (the RTS owns threads that still reference it).
// The library handle and StablePtr state therefore leak by design at
// destruction — see `~FfiBackend` for the implementation.
class FfiBackend : public IBackend {
    void* handle_ = nullptr;
    AletheiaInitFn init_fn_ = nullptr;
    AletheiaProcessFn process_fn_ = nullptr;
    AletheiaSendFrameFn send_frame_fn_ = nullptr;
    AletheiaFreeStrFn free_str_fn_ = nullptr;
    AletheiaCloseFn close_fn_ = nullptr;
    AletheiaSendErrorFn send_error_fn_ = nullptr;
    AletheiaSendRemoteFn send_remote_fn_ = nullptr;
    AletheiaNoArgFn start_stream_fn_ = nullptr;
    AletheiaNoArgFn end_stream_fn_ = nullptr;
    AletheiaNoArgFn format_dbc_fn_ = nullptr;
    AletheiaExtractFn extract_signals_fn_ = nullptr;
    AletheiaBuildFrameBinFn build_frame_bin_fn_ = nullptr;
    AletheiaUpdateFrameBinFn update_frame_bin_fn_ = nullptr;
    AletheiaExtractBinFn extract_signals_bin_fn_ = nullptr;
    AletheiaFreeBufFn free_buf_fn_ = nullptr;
    // Populated when the backend detects that the GHC RTS was already
    // initialised with a different -N value than the caller requested.
    // Emitted by Client as the `rts.cores_mismatch` structured log event
    // with `active_cores` / `requested_cores` fields (Go + Python parity).
    std::optional<std::pair<int, int>> rts_mismatch_;

    template<typename Fn>
    static auto load_sym(void* handle, const char* name) -> Fn {
        auto* sym = dlsym(handle, name);
        if (sym == nullptr)
            throw AletheiaException(AletheiaError{ErrorKind::Ffi, std::string("dlsym failed for ") +
                                                                      name + ": " + dlerror()});
        // dlsym returns void*; POSIX guarantees round-tripping through void*
        // preserves function pointers on all platforms with dlopen support.
        // NOLINTNEXTLINE(cppcoreguidelines-pro-type-reinterpret-cast)
        return reinterpret_cast<Fn>(sym);
    }

    // Wrap an FFI char* result with the standard null-check + RAII deleter
    // + std::string conversion pattern.  Throws AletheiaException with
    // ErrorKind::Protocol and `error_msg` when result is null; otherwise
    // materializes the C string into a std::string and frees the FFI
    // buffer via free_str_fn_.  Protocol is the correct kind here per the
    // narrow definition of ErrorKind::Ffi in error.hpp ("Library load /
    // RTS initialization failure" — boundary itself failed before Agda
    // ran); a runtime null-return means the kernel was loaded but did
    // not produce a response, which mirrors the ProtocolError the Python
    // client raises for the same condition.  Every string-returning
    // endpoint below goes through it.
    [[nodiscard]] auto wrap_str_result(char* result, std::string_view error_msg) -> std::string {
        if (result == nullptr)
            throw AletheiaException(AletheiaError{ErrorKind::Protocol, std::string{error_msg}});
        auto deleter = [this](char* p) { free_str_fn_(p); };
        const std::unique_ptr<char, decltype(deleter)> guard{result, deleter};
        return std::string{result};
    }

public:
    // Both arguments are validated before the library is opened: a refused
    // construction must load nothing (dlopen of an empty path opens the
    // calling program, and a handle opened before a throw would leak, since
    // the destructor deliberately never closes one).
    explicit FfiBackend(const std::filesystem::path& lib_path, int rts_cores) {
        if (rts_cores < 1)
            throw AletheiaException(AletheiaError{
                ErrorKind::Validation, "rts_cores must be >= 1, got " + std::to_string(rts_cores)});
        if (lib_path.empty())
            throw AletheiaException(
                AletheiaError{ErrorKind::Validation,
                              "library path is empty: pass the path of libaletheia-ffi.so"});
        handle_ = dlopen(lib_path.c_str(), RTLD_NOW | RTLD_LOCAL);
        if (handle_ == nullptr)
            throw AletheiaException(
                AletheiaError{ErrorKind::Ffi, std::string("dlopen failed: ") + dlerror()});

        try {
            auto hs_init =
                load_sym<HsInitFn>(handle_, std::string{detail::rts_init_symbol}.c_str());
            init_fn_ = load_sym<AletheiaInitFn>(handle_, "aletheia_init");
            process_fn_ = load_sym<AletheiaProcessFn>(handle_, "aletheia_process");
            send_frame_fn_ = load_sym<AletheiaSendFrameFn>(handle_, "aletheia_send_frame");
            free_str_fn_ = load_sym<AletheiaFreeStrFn>(handle_, "aletheia_free_str");
            close_fn_ = load_sym<AletheiaCloseFn>(handle_, "aletheia_close");
            send_error_fn_ = load_sym<AletheiaSendErrorFn>(handle_, "aletheia_send_error");
            send_remote_fn_ = load_sym<AletheiaSendRemoteFn>(handle_, "aletheia_send_remote");
            start_stream_fn_ = load_sym<AletheiaNoArgFn>(handle_, "aletheia_start_stream");
            end_stream_fn_ = load_sym<AletheiaNoArgFn>(handle_, "aletheia_end_stream");
            format_dbc_fn_ = load_sym<AletheiaNoArgFn>(handle_, "aletheia_format_dbc");
            extract_signals_fn_ = load_sym<AletheiaExtractFn>(handle_, "aletheia_extract_signals");
            build_frame_bin_fn_ =
                load_sym<AletheiaBuildFrameBinFn>(handle_, "aletheia_build_frame_bin");
            update_frame_bin_fn_ =
                load_sym<AletheiaUpdateFrameBinFn>(handle_, "aletheia_update_frame_bin");
            extract_signals_bin_fn_ =
                load_sym<AletheiaExtractBinFn>(handle_, "aletheia_extract_signals_bin");
            free_buf_fn_ = load_sym<AletheiaFreeBufFn>(handle_, "aletheia_free_buf");

            // Initialize GHC RTS (once per process, never finalized).  The
            // init state is shared with `rational_renderer.cpp` through
            // `detail::rts_init_state()`, so the first backend's core count is
            // visible to every later one and a different request surfaces as
            // the `rts.cores_mismatch` warning instead of being dropped.
            auto& rts = detail::rts_init_state();
            const std::scoped_lock lock(rts.mu);
            if (!rts.initialized) {
                // The argv always carries the containment heap cap.
                // hs_init_with_rtsopts may retain argv for the whole process
                // lifetime, so the backing storage must outlive this call:
                // function-local statics give process-lifetime storage without
                // a raw owning `new`, and this block runs exactly once
                // (guarded by rts.initialized under rts.mu), so their
                // runtime-valued initialisers evaluate once.
                const char* override_env =
                    std::getenv(std::string{detail::rts_override_env}.c_str());
                static std::vector<std::string> rts_argv =
                    detail::rts_init_args(rts_cores, override_env != nullptr ? override_env : "");
                static std::vector<char*> rts_argv_ptrs = [] {
                    std::vector<char*> ptrs;
                    ptrs.reserve(rts_argv.size());
                    for (auto& arg : rts_argv)
                        ptrs.push_back(arg.data());
                    return ptrs;
                }();
                auto argc = static_cast<int>(rts_argv_ptrs.size());
                auto** argv = rts_argv_ptrs.data();
                hs_init(&argc, &argv);
                rts.cores = rts_cores;
                rts.initialized = true;
            } else if (auto mismatch = detail::rts_cores_mismatch(rts_cores, rts.cores)) {
                rts_mismatch_ = *mismatch;
            }
        } catch (...) {
            // RTS was never started — safe to release the library handle.
            dlclose(handle_);
            throw;
        }
    }

    // See class-level docstring for the no-hs_exit / no-dlclose rationale.
    ~FfiBackend() override = default;

    FfiBackend(const FfiBackend&) = delete;
    FfiBackend& operator=(const FfiBackend&) = delete;
    FfiBackend(FfiBackend&&) = delete;
    FfiBackend& operator=(FfiBackend&&) = delete;

    [[nodiscard]] auto rts_mismatch_info() const -> std::optional<std::pair<int, int>> override {
        return rts_mismatch_;
    }

    auto init() -> BackendState override { return BackendState{*this, init_fn_()}; }

    auto process(const BackendState& state, std::string_view input) -> std::string override {
        // Adversarial-input bound: synthesize an error response before
        // marshaling oversize inputs into Haskell, per AGENTS.md universal
        // rule "Adversarial-input bounds at parser surfaces".  The Agda
        // kernel enforces the same bound; this is the C++ binding's
        // short-circuit so we do not allocate an N-byte std::string + a
        // C-side null-terminated copy only to be rejected on the other
        // side.  Returns the wire-format error JSON so the existing
        // `detail::parse_*` paths translate to AletheiaError with
        // code == ErrorCode::InputBoundExceeded uniformly after
        // consolidation.
        if (input.size() > aletheia::max_json_bytes) {
            // Emit structured bound_kind /
            // observed / limit fields alongside `code` and `message` so
            // downstream `parse_*` paths can lift them into the
            // AletheiaError's optional InputBoundExceededError, matching
            // Python's typed `InputBoundExceededError(...)` shape and Go's
            // `*InputBoundExceededError{Kind/Observed/Limit/Code}`.
            std::string out;
            out.reserve(256);
            out.append(
                R"({"status":"error","code":"input_bound_exceeded","message":"input length (bytes) )");
            out.append(std::to_string(input.size()));
            out.append(R"( exceeds limit )");
            out.append(std::to_string(aletheia::max_json_bytes));
            out.append(R"(","bound_kind":")");
            out.append(aletheia::bound_kind_input_length_bytes);
            out.append(R"(","observed":)");
            out.append(std::to_string(input.size()));
            out.append(R"(,"limit":)");
            out.append(std::to_string(aletheia::max_json_bytes));
            out.append(R"(})");
            return out;
        }
        // The Agda core expects a null-terminated string.
        const std::string input_str{input};
        return wrap_str_result(process_fn_(state.get(), input_str.c_str()),
                               "aletheia_process returned null");
    }

    auto send_frame_binary(const BackendState& state, Timestamp ts, const CanId& id, Dlc dlc,
                           std::span<const std::byte> data, std::optional<bool> brs,
                           std::optional<bool> esi) -> std::string override {
        const auto timestamp = static_cast<std::uint64_t>(ts.count());
        const auto [can_id, extended] = wire_can_id(id);
        const auto dlc_val = dlc.value();
        if (auto err = payload_bound_error(data))
            throw AletheiaException(*err);
        const auto data_len = static_cast<std::uint8_t>(data.size());

        // Encode optional<bool> as (present, value) byte pairs — inverse
        // of the Haskell shim's mkMaybeBool.
        const auto encode = [](std::optional<bool> b) -> std::pair<std::uint8_t, std::uint8_t> {
            if (!b.has_value())
                return {0, 0};
            return {1, static_cast<std::uint8_t>(*b ? 1 : 0)};
        };
        const auto [brs_p, brs_v] = encode(brs);
        const auto [esi_p, esi_v] = encode(esi);

        return wrap_str_result(send_frame_fn_(state.get(), timestamp, can_id, extended, dlc_val,
                                              as_u8(data.data()), data_len, brs_p, brs_v, esi_p,
                                              esi_v),
                               "aletheia_send_frame returned null");
    }

    auto send_error_binary(const BackendState& state, Timestamp ts) -> std::string override {
        const auto timestamp = static_cast<std::uint64_t>(ts.count());
        return wrap_str_result(send_error_fn_(state.get(), timestamp),
                               "aletheia_send_error returned null");
    }

    auto send_remote_binary(const BackendState& state, Timestamp ts, const CanId& id)
        -> std::string override {
        const auto timestamp = static_cast<std::uint64_t>(ts.count());
        const auto [can_id, extended] = wire_can_id(id);
        return wrap_str_result(send_remote_fn_(state.get(), timestamp, can_id, extended),
                               "aletheia_send_remote returned null");
    }

    auto start_stream_binary(const BackendState& state) -> std::string override {
        return wrap_str_result(start_stream_fn_(state.get()),
                               "aletheia_start_stream returned null");
    }

    auto end_stream_binary(const BackendState& state) -> std::string override {
        return wrap_str_result(end_stream_fn_(state.get()), "aletheia_end_stream returned null");
    }

    auto format_dbc_binary(const BackendState& state) -> std::string override {
        return wrap_str_result(format_dbc_fn_(state.get()), "aletheia_format_dbc returned null");
    }

    auto extract_signals_binary(const BackendState& state, const CanId& id, Dlc dlc,
                                std::span<const std::byte> data) -> std::string override {
        const auto [can_id, extended] = wire_can_id(id);
        const auto dlc_val = dlc.value();
        if (auto err = payload_bound_error(data))
            throw AletheiaException(*err);
        const auto data_len = static_cast<std::uint8_t>(data.size());

        return wrap_str_result(extract_signals_fn_(state.get(), can_id, extended, dlc_val,
                                                   as_u8(data.data()), data_len),
                               "aletheia_extract_signals returned null");
    }

    auto build_frame_bin(const BackendState& state, const CanId& id, Dlc dlc,
                         SignalInjection signals, std::size_t expected_bytes)
        -> std::expected<std::vector<std::byte>, AletheiaError> override {
        const auto [can_id, extended] = wire_can_id(id);

        std::vector<std::byte> buf(expected_bytes);
        char* err_str = nullptr;
        const auto status =
            build_frame_bin_fn_(state.get(), can_id, extended, dlc.value(), signals.count(),
                                signals.indices().data(), signals.numerators().data(),
                                signals.denominators().data(), as_u8(buf.data()), &err_str);
        if (auto err = detail::ffi_error_from_status(status, err_str, free_str_fn_))
            return std::unexpected(*err);
        return buf;
    }

    auto update_frame_bin(const BackendState& state, const CanId& id, Dlc dlc,
                          std::span<const std::byte> data, SignalInjection signals,
                          std::size_t expected_bytes)
        -> std::expected<std::vector<std::byte>, AletheiaError> override {
        if (auto err = payload_bound_error(data))
            return std::unexpected(*err);
        const auto [can_id, extended] = wire_can_id(id);
        const auto data_len = static_cast<std::uint8_t>(data.size());

        std::vector<std::byte> buf(expected_bytes);
        char* err_str = nullptr;
        const auto status = update_frame_bin_fn_(
            state.get(), can_id, extended, dlc.value(), as_u8(data.data()), data_len,
            signals.count(), signals.indices().data(), signals.numerators().data(),
            signals.denominators().data(), as_u8(buf.data()), &err_str);
        if (auto err = detail::ffi_error_from_status(status, err_str, free_str_fn_))
            return std::unexpected(*err);
        return buf;
    }

    auto extract_signals_bin(const BackendState& state, const CanId& id, Dlc dlc,
                             std::span<const std::byte> data)
        -> std::expected<std::vector<std::byte>, AletheiaError> override {
        if (auto err = payload_bound_error(data))
            return std::unexpected(*err);
        const auto [can_id, extended] = wire_can_id(id);
        const auto data_len = static_cast<std::uint8_t>(data.size());

        std::uint8_t* out_buf = nullptr;
        std::uint32_t out_size = 0;
        char* err_str = nullptr;
        const auto status =
            extract_signals_bin_fn_(state.get(), can_id, extended, dlc.value(), as_u8(data.data()),
                                    data_len, &out_buf, &out_size, &err_str);
        if (auto err = detail::ffi_error_from_status(status, err_str, free_str_fn_))
            return std::unexpected(*err);
        // RAII-owned so a throwing std::vector construction (e.g. bad_alloc on
        // copy) still frees the Haskell-allocated buffer. A bare free call
        // after the copy would leak on that path.
        const std::unique_ptr<std::uint8_t, AletheiaFreeBufFn> out_guard(out_buf, free_buf_fn_);
        // Guard against the degenerate case where the backend signalled
        // success but produced a null buffer: constructing std::span from a
        // null pointer with non-zero size is undefined behaviour
        // ([span.cons]/3). A zero-length extraction is a legal successful
        // response — return an empty payload instead of reading through null.
        if (out_buf == nullptr)
            return std::vector<std::byte>{};
        const std::span<const std::byte> out_bytes(as_byte(out_buf), out_size);
        return std::vector<std::byte>(out_bytes.begin(), out_bytes.end());
    }

protected:
    // Reached only through BackendState, which is the sole owner of the state
    // this releases.
    void close(void* state) override { close_fn_(state); }
};

} // anonymous namespace

auto make_ffi_backend(const std::filesystem::path& lib_path, int rts_cores)
    -> std::unique_ptr<IBackend> {
    // The backend validates its arguments and opens the library; registering
    // the path first would leave the renderer pointing at a path this call is
    // about to refuse, so the backend is constructed before the registration.
    auto backend = std::make_unique<FfiBackend>(lib_path, rts_cores);
    // The lazy-loaded Rational renderer (`rational_renderer.cpp`) then prefers
    // the same .so instead of its relative-path heuristic.
    detail::register_default_lib_path(lib_path);
    return backend;
}

auto make_ffi_backend_from_env(int rts_cores) -> std::unique_ptr<IBackend> {
    // std::getenv returns nullptr when unset, but a valid pointer to "" when
    // set-but-empty (ALETHEIA_LIB=) — guard BOTH, or we would dlopen("").
    const char* env = std::getenv("ALETHEIA_LIB");
    if (env == nullptr || *env == '\0')
        throw AletheiaException(
            AletheiaError{ErrorKind::Validation,
                          "ALETHEIA_LIB is not set — set it to the path of libaletheia-ffi.so, "
                          "or call make_ffi_backend(path)"});
    return make_ffi_backend(std::filesystem::path{env}, rts_cores);
}

