// ===========================================================================
// Rational comparison
// ===========================================================================

TEST_CASE("Rational operator<=> and operator==", "[types]") {
    Rational a{1, 2};  // 0.5
    Rational b{2, 4};  // 0.5
    Rational c{3, 4};  // 0.75
    Rational d{-1, 2}; // -0.5

    SECTION("equality") {
        CHECK(a == b);
        CHECK_FALSE(a == c);
    }

    SECTION("less than") {
        CHECK(a < c);
        CHECK(d < a);
        CHECK_FALSE(c < a);
    }

    SECTION("greater than") {
        CHECK(c > a);
        CHECK_FALSE(a > c);
    }

    SECTION("less than or equal") {
        CHECK(a <= b);
        CHECK(a <= c);
        CHECK_FALSE(c <= a);
    }

    SECTION("negative values") {
        Rational neg{-3, 4};
        CHECK(neg < a);
        CHECK(d == Rational{-1, 2});
    }
}

